{
  "updates": [
    {
      "question_id": "Q1",
      "answered_aspects": [
        {
          "aspect_id": "Q1-A1",
          "claim": "程炎震系仲堪為荊州於太元十七年，可作為『值水儉』發生時間的背景。",
          "evidence": [
            {
              "ref": "J01",
              "quote": "程炎震云：「太元十七年，仲堪為荊州。」"
            }
          ]
        },
        {
          "aspect_id": "Q1-A2",
          "claim": "余嘉錫認為仲堪之儉是出於鄙吝天性，而非單純為官表率。",
          "evidence": [
            {
              "ref": "J02",
              "quote": "然則仲堪之儉，特鄙吝之天性耳"
            }
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q1-U1",
          "gap": "『水儉』一詞的具體所指未見注解：注家未說明其為水災歉收、水患荒年或其他與水相關的儉歲。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [
        {
          "conflict_id": "Q1-C1",
          "description": "正文稱仲堪『性真素』，余嘉錫則斷其儉為『鄙吝之天性』，對仲堪儉約的品性評價相反。",
          "evidence": [
            {
              "ref": "primary_text",
              "quote": "雖欲率物亦縁其性真素"
            },
            {
              "ref": "J02",
              "quote": "然則仲堪之儉，特鄙吝之天性耳"
            }
          ]
        },
        {
          "conflict_id": "Q1-C2",
          "description": "余嘉錫所引《晉書》稱仲堪『嗇於周急』，所引《道學傳》則稱其『時行周救，弘益不少』，二說對仲堪是否周濟他人互相矛盾。",
          "evidence": [
            {
              "ref": "J02",
              "quote": "晉書本傳云：「仲堪少奉天師道，又精心事神，不吝財賄，而怠行仁義，嗇於周急。」"
            },
            {
              "ref": "J02",
              "quote": "道學傳第十六卷云：「殷仲堪者，陳郡人也。……時行周救，弘益不少也。」"
            }
          ]
        }
      ],
      "reading_sufficient": false,
      "historical_verification_open": true
    },
    {
      "question_id": "Q2",
      "answered_aspects": [],
      "unanswered_aspects": [
        {
          "aspect_id": "Q2-U1",
          "gap": "『豁』在『云我豁平昔時意』中的具體語義（豁達、棄置、改變等）未見注釋，直接影響對句意的理解。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": false
    },
    {
      "question_id": "Q3",
      "answered_aspects": [
        {
          "aspect_id": "Q3-A1",
          "claim": "余嘉錫引《說苑》《家語》中榮啟期『貧者士之常』語，可佐證『貧者士之常』的典故來源。",
          "evidence": [
            {
              "ref": "J04",
              "quote": "說苑雜言篇云：「孔子見榮啟期問曰：『先生何樂也？』對曰：『夫貧者，士之常也；死者，民之終也。處常待終，當何憂乎？』」"
            }
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q3-U1",
          "gap": "『登枝』與『捐本』的比喻對應關係未得到注釋說明：是否以登枝喻受任方州、捐本喻忘棄貧士本分，材料中未明言。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": false
    }
  ]
}

